import {validatePaperUpload} from './paper-upload-policy.mjs';
import {selectableProjects,projectPickerOptions,subscribeProjectDirectory} from './project-directory.mjs';
import {mountAigcDetection} from './aigc-detection.mjs';
import {mountWebSimilarity,ensureWebSimilarityStyle} from './web-similarity.mjs';
import {withStableView} from './view-stability.mjs';
import {toolBanner} from './tool-banner.mjs';
import {parseDocument,countChars,compileSources,compareParagraph,buildReport,LIMITS} from '../precheck/engine.mjs';
import {repository} from '../precheck/store.mjs';
import {selectedDetectionSections,detectionChars,selectDetectionReports,validateDetectionSource} from './detection-model.mjs';
